     "code": "colours = {\"red\", \"green\", \"red\", \"blue\", \"green\"}\nprint(len(colours))\nprint(\"red\" in colours)\nprint(set([1, 2, 2, 3, 3, 3]))\nprint(set(\"hello\"))",
