     "code": "STAGES = [\n    \"  +---+\\n  |   |\\n      |\\n      |\\n      |\\n      |\\n=========\",\n    \"  +---+\\n  |   |\\n  O   |\\n      |\\n      |\\n      |\\n=========\",\n    \"  +---+\\n  |   |\\n  O   |\\n  |   |\\n      |\\n      |\\n=========\",\n    \"  +---+\\n  |   |\\n  O   |\\n /|\\\\  |\\n      |\\n      |\\n=========\",\n    \"  +---+\\n  |   |\\n  O   |\\n /|\\\\  |\\n / \\\\  |\\n      |\\n=========\",\n]\nfor wrong in (0, 2, 4):\n    print(STAGES[wrong])\n    print()",
